#!/usr/bin/env bash
# G-A085 precision evaluation (no training, no reward change).  Generated by
# tools/build_go2_g_a085_package.py from this template.
#
#   bash run_all.sh            preflight, then tmux session go2_g_a085 runs --inner
#
# What it does, in order (a rerun of the same line continues: measured cases are kept
# through the evaluator's own case fingerprints, GO2_RESUME semantics):
#   1. resolve the three iter-2400 policies (A082/A083 shipped in the package, A084 from
#      this PC's own G-A084 result folder, accepted only when RUNNER_RC=0 and the model
#      SHA equals its CHECKPOINT_PIN.txt)
#   2. six new evaluation seeds per policy as two 69-case suites (404/505/606, 707/808/909)
#   3. diagnostic replay (roll/pitch, foot contact) of the fall cases for A083 and A084 on
#      the original seeds, compared byte-for-byte with the stored original steps.csv
#   4. standard-library analysis -> analysis/ROWS.csv, SUMMARY.json
#   5. two archives: a small SUMMARY ZIP (analysis, summaries, identities, diag) and the
#      full RESULT ZIP (every steps.csv), each with .sha256
# The evaluation functions between BEGIN/END RUNNER EVAL FUNCTIONS are byte-identical to
# the G-A084 runner (asserted by tools/test_go2_g_a085_package.py).
set -euo pipefail
ROOT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
ISAACLAB_SH=${ISAACLAB_SH:-/workspace/IsaacLab/isaaclab.sh}
KB=${GO2_A085_KEEP_BASE:-/workspace/_keep}
SESSION=go2_g_a085
KEEP="$KB/go2_g_a085_precision_eval"
WORK=${GO2_A085_WORK:-/workspace/go2_g_a085_work}
STATUS="$KB/GO2_G_A085_STATUS.txt"
RESULT_ZIP="$KB/GO2_G_A085_PRECISION_EVAL_RESULT.zip"
SUMMARY_ZIP="$KB/GO2_G_A085_PRECISION_EVAL_SUMMARY.zip"
A084_KEEP=${GO2_A085_A084_KEEP:-$KB/go2_g_a084_ang_vel_xy_m0p065}  # override for the contract test only
NEW_SEED_SETS=("404 505 606" "707 808 909")
DIAG_SEEDS=(101 202 303)
DIAG_CASES=("G3 rough_forward" "G3 rough_lateral" "G6 push_pos_x" "G6 push_neg_x" "G6 push_pos_y")
EXPECTED_EVALUATOR_SHA=@EVALUATOR_SHA@
A082_MODEL_SHA=@A082_MODEL_SHA@
A082_ENV_SHA=@A082_ENV_SHA@
A083_MODEL_SHA=@A083_MODEL_SHA@
A083_ENV_SHA=@A083_ENV_SHA@
A082_STORED=${GO2_A085_A082_STORED:-$KB/go2_g_a082_track_ang_vel_z_p0p75/evaluation/candidate}
A083_STORED=${GO2_A085_A083_STORED:-$KB/go2_g_a083_action_rate_m0p01/evaluation/candidate}
A084_STORED="$A084_KEEP/evaluation/candidate"

sha() { sha256sum "$1" | awk '{print $1}'; }

if [[ "${1:-}" != --inner ]]; then
  (cd "$ROOT_DIR" && sha256sum -c --quiet SHA256SUMS.txt) || { echo '[FAIL] package checksum mismatch'; exit 25; }
  [[ -x "$ISAACLAB_SH" ]] || { echo "[FAIL] missing $ISAACLAB_SH"; exit 22; }
  command -v tmux >/dev/null || { echo '[FAIL] tmux missing'; exit 22; }
  nvidia-smi >/dev/null || { echo '[FAIL] nvidia-smi failed'; exit 22; }
  tmux has-session -t "$SESSION" 2>/dev/null && { echo "[FAIL] tmux session $SESSION already exists"; exit 21; }
  if pgrep -af 'train.py|play.py' >/dev/null 2>&1; then echo '[FAIL] another train.py/play.py is running'; exit 21; fi
  free_gb=$(df -BG --output=avail "$KB" 2>/dev/null | tail -1 | tr -dc 0-9) || free_gb=
  [[ -z "$free_gb" || "$free_gb" -ge 15 ]] || { echo "[FAIL] less than 15 GB free under $KB"; exit 20; }
  grep -qx 'RUNNER_RC=0' "$A084_KEEP/RUNNER_STATUS.txt" 2>/dev/null || {
    echo "[WAIT] G-A084 has not finished with RUNNER_RC=0 ($A084_KEEP/RUNNER_STATUS.txt); nothing started"; exit 26; }
  if [[ -e "$KEEP" && ! -s "$KEEP/G_A085_OWNER.txt" ]]; then echo "[FAIL] $KEEP exists and is not this evaluation"; exit 33; fi
  printf -v cmd 'ISAACLAB_SH=%q GO2_A085_KEEP_BASE=%q GO2_A085_WORK=%q GO2_A085_A084_KEEP=%q GO2_A085_A082_STORED=%q GO2_A085_A083_STORED=%q bash %q --inner; echo; echo "[PANE KEPT OPEN] status: cat %q"; exec bash' \
    "$ISAACLAB_SH" "$KB" "$WORK" "$A084_KEEP" "$A082_STORED" "$A083_STORED" "$ROOT_DIR/go2_g_a085_eval.sh" "$STATUS"
  tmux new-session -d -s "$SESSION" "$cmd"
  echo "[STARTED] tmux attach -t $SESSION   (detach: Ctrl+B, D)"
  echo "[PROGRESS] cat $STATUS"
  echo "[ESTIMATE] 6 suites x ~45 min + 32 diag runs ~30 min + packaging ~15 min = about 5 h"
  exit 0
fi

mkdir -p "$KEEP/logs" "$KEEP/meta" "$KEEP/evaluation" "$KEEP/diag" "$KEEP/analysis"
[[ -s "$KEEP/G_A085_OWNER.txt" ]] || printf 'WORK_ID=G-A085\nCREATED_AT=%s\n' "$(date -Is)" >"$KEEP/G_A085_OWNER.txt"
exec > >(tee -a "$KEEP/logs/G_A085_RUN.log") 2>&1
export PYTHONUTF8=1 PYTHONIOENCODING=utf-8 PYTHONUNBUFFERED=1

PHASE=preflight
write_status() {  # state rc note
  {
    echo "STATE=$1"; echo "RC=$2"; echo "PHASE=$PHASE"
    for d in "$KEEP"/evaluation/*/; do
      [[ -d "$d" ]] && echo "SUITE_$(basename "$d")=$(find "$d/cases" -name summary.json 2>/dev/null | wc -l)/69"
    done
    echo "DIAG_RUNS=$(find "$KEEP/diag" -name summary.json 2>/dev/null | wc -l)/32"
    echo "SUMMARY_ZIP=$([[ -s "$SUMMARY_ZIP" ]] && echo "$SUMMARY_ZIP" || echo ABSENT)"
    echo "RESULT_ZIP=$([[ -s "$RESULT_ZIP" ]] && echo "$RESULT_ZIP" || echo ABSENT)"
    echo "NOTE=$3"; echo "UPDATED_AT=$(date -Is)"
  } >"$STATUS.tmp"
  mv "$STATUS.tmp" "$STATUS"
}
trap 'code=$?; if grep -qx "STATE=RUNNING" "$STATUS" 2>/dev/null; then write_status FAILED "$code" "exited during $PHASE; rerun the same line to continue (measured cases are kept)"; fi' EXIT
write_status RUNNING - 'preflight'

(cd "$ROOT_DIR" && sha256sum -c --quiet SHA256SUMS.txt) || { write_status FAILED 25 'package checksum mismatch'; exit 25; }
PY=()
if [[ -x "$ISAACLAB_SH" ]]; then PY=("$ISAACLAB_SH" -p)
elif command -v python3 >/dev/null 2>&1; then PY=(python3)
else PY=(python); fi
POSTURE_CHECK="$ROOT_DIR/shared/posture_contract_check.py"
REGISTRY="$ROOT_DIR/shared/go2_self_eval_registry.json"
REGISTRY_SHA=$(sha "$REGISTRY")
EVAL_STEPS=1000
RESUME=1
EVALUATOR_SHA=$(sha "$ROOT_DIR/shared/eval_root/go2_eval_telemetry.py")
[[ "$EVALUATOR_SHA" == "$EXPECTED_EVALUATOR_SHA" ]] || { write_status FAILED 23 'evaluator is not the G-A082..G-A084 ruler'; exit 23; }

# ---- policies -------------------------------------------------------------------------------
grep -qx 'RUNNER_RC=0' "$A084_KEEP/RUNNER_STATUS.txt" || { write_status FAILED 26 'G-A084 RUNNER_RC is not 0'; exit 26; }
A084_MODEL_SHA=$(sed -n 's/^EVAL_CHECKPOINT_SHA=//p' "$A084_KEEP/training/CHECKPOINT_PIN.txt")
[[ "$(sha "$A084_KEEP/training/model_best.pt")" == "$A084_MODEL_SHA" ]] || {
  write_status FAILED 23 'G-A084 model_best.pt is not its pinned iter-2400 checkpoint'; exit 23; }
A084_ENV_SHA=$(sha "$A084_KEEP/training/env.yaml")
grep -Fq "\"model_sha256\":\"$A084_MODEL_SHA\"" "$A084_STORED/identity.json" &&
  grep -Fq "\"env_sha256\":\"$A084_ENV_SHA\"" "$A084_STORED/identity.json" &&
  grep -Fq "\"evaluator_sha256\":\"$EXPECTED_EVALUATOR_SHA\"" "$A084_STORED/identity.json" || {
  write_status FAILED 23 'G-A084 stored evaluation identity does not match its model/env/evaluator'; exit 23; }
declare -A MODEL ENV REWARDS MSHA STORED
MODEL[a082]="$ROOT_DIR/policies/a082/model_best.pt"; ENV[a082]="$ROOT_DIR/policies/a082/env.yaml"
REWARDS[a082]="$ROOT_DIR/policies/a082/quadruped_rewards.py"; MSHA[a082]=$A082_MODEL_SHA; STORED[a082]=$A082_STORED
MODEL[a083]="$ROOT_DIR/policies/a083/model_best.pt"; ENV[a083]="$ROOT_DIR/policies/a083/env.yaml"
REWARDS[a083]="$ROOT_DIR/policies/a083/quadruped_rewards.py"; MSHA[a083]=$A083_MODEL_SHA; STORED[a083]=$A083_STORED
MODEL[a084]="$A084_KEEP/training/model_best.pt"; ENV[a084]="$A084_KEEP/training/env.yaml"
REWARDS[a084]="$A084_KEEP/training/source/quadruped_rewards.py"; MSHA[a084]=$A084_MODEL_SHA; STORED[a084]=$A084_STORED
[[ "$(sha "${ENV[a082]}")" == "$A082_ENV_SHA" && "$(sha "${ENV[a083]}")" == "$A083_ENV_SHA" ]] || {
  write_status FAILED 23 'shipped A082/A083 env SHA mismatch'; exit 23; }
[[ -s "${REWARDS[a084]}" ]] || { write_status FAILED 23 'G-A084 training/source/quadruped_rewards.py missing'; exit 23; }
{
  for k in a082 a083 a084; do
    printf '%s model=%s env=%s rewards=%s stored=%s\n' "$k" "$(sha "${MODEL[$k]}")" "$(sha "${ENV[$k]}")" "$(sha "${REWARDS[$k]}")" "${STORED[$k]}"
  done
  echo "evaluator=$EVALUATOR_SHA registry=$REGISTRY_SHA"
} >"$KEEP/meta/POLICIES.txt"
cp -a "$ROOT_DIR/experiment.json" "$ROOT_DIR/SHA256SUMS.txt" "$KEEP/meta/"
nvidia-smi --query-gpu=name,driver_version,memory.total --format=csv,noheader >"$KEEP/meta/gpu.csv" || true

make_root() {  # key plain|diag -> echo path
  local key=$1 kind=$2 dir="$WORK/${key}_$2"
  if [[ ! -s "$dir/ROOT_OK" ]]; then
    rm -rf -- "$dir"; mkdir -p "$dir"
    cp -a "$ROOT_DIR/shared/eval_root/." "$dir/"
    cp -a "${REWARDS[$key]}" "$dir/quadruped_rewards.py"
    if [[ "$kind" == diag ]]; then
      cp -a "$ROOT_DIR/shared/eval_root/go2_eval_telemetry.py" "$dir/go2_eval_telemetry_v6.py"
      cp -a "$ROOT_DIR/shared/diag/go2_eval_telemetry_diag_wrapper_v2.py" "$dir/go2_eval_telemetry.py"
      cp -a "$ROOT_DIR/shared/diag/go2_eval_diag_v2.py" "$dir/go2_eval_diag_v2.py"
    fi
    echo ok >"$dir/ROOT_OK"
  fi
  echo "$dir"
}

# ---- BEGIN RUNNER EVAL FUNCTIONS (byte-identical to the G-A084 runner) ----
@EVAL_FUNCTIONS@
# ---- END RUNNER EVAL FUNCTIONS ----

GO2_USD_URL='https://omniverse-content-production.s3-us-west-2.amazonaws.com/Assets/Isaac/5.1/Isaac/IsaacLab/Robots/Unitree/Go2/go2.usd'
if command -v curl >/dev/null 2>&1; then
  curl --fail --silent --show-error --location --head --connect-timeout 10 --max-time 45 "$GO2_USD_URL" >/dev/null || {
    write_status FAILED 25 'Go2 USD asset is unavailable; nothing evaluated'; exit 25; }
fi

run_suites() {  # key
  local key=$1 root set
  root=$(make_root "$key" plain)
  for set in "${NEW_SEED_SETS[@]}"; do
    read -r -a SEEDS <<<"$set"
    PHASE="suite ${key} seeds ${set}"
    write_status RUNNING - "$PHASE"
    run_full_suite "${key}_s${SEEDS[0]}" "$root" "${MODEL[$key]}" "${ENV[$key]}" "${MSHA[$key]}"
  done
}

run_diag() {  # key
  local key=$1 root seed spec scen case_id out saved_sha=$EVALUATOR_SHA
  root=$(make_root "$key" diag)
  PHASE="diag ${key}"
  write_status RUNNING - "$PHASE"
  stage_policy "$root" "${MODEL[$key]}" "${ENV[$key]}"
  [[ "$ACTIVE_MODEL_SHA" == "${MSHA[$key]}" ]] || { write_status FAILED 7 "$key diag model SHA mismatch"; exit 7; }
  EVALUATOR_SHA=$(sha "$root/go2_eval_telemetry.py")  # resume fingerprint of the diag ruler
  out="$KEEP/diag/$key"
  write_identity "${key}_diag" "$root" "${MODEL[$key]}" "${ENV[$key]}" "$out"
  for seed in "${DIAG_SEEDS[@]}"; do
    for spec in "${DIAG_CASES[@]}"; do
      read -r scen case_id <<<"$spec"
      run_eval_case "${key}_diag" "$root" "$seed" "$scen" "$case_id" "$out"
    done
  done
  run_eval_case "${key}_diag" "$root" 101 G7 dr_seed_101 "$out"
  EVALUATOR_SHA=$saved_sha
  for f in $(cd "$out/cases" && find . -name steps.csv | sort); do
    if [[ ! -s "${STORED[$key]}/cases/$f" ]]; then r=STORED_MISSING
    elif cmp -s "$out/cases/$f" "${STORED[$key]}/cases/$f"; then r=IDENTICAL
    else r=DIFFERENT; fi
    echo "${key} ${f#./} $r"
  done >"$KEEP/diag/${key}_PLAIN_VS_DIAG.txt"
  cd "$ROOT_DIR"
}

run_suites a083
run_suites a084
run_diag a083
run_diag a084
run_suites a082

PHASE=analysis
write_status RUNNING - 'standard-library analysis'
arms=()
for k in a082 a083 a084; do
  [[ -d "${STORED[$k]}/cases" ]] && arms+=(--arm "$k=${STORED[$k]}")
  for set in "${NEW_SEED_SETS[@]}"; do arms+=(--arm "$k=$KEEP/evaluation/${k}_s${set%% *}"); done
done
"${PY[@]}" "$ROOT_DIR/shared/go2_g_a085_precision_analysis.py" "${arms[@]}" --out "$KEEP/analysis" \
  >"$KEEP/analysis/ANALYSIS.log" 2>&1 || { write_status FAILED 30 'analysis failed (see analysis/ANALYSIS.log)'; exit 30; }
for k in a082 a083 a084; do
  [[ -d "${STORED[$k]}/cases" ]] && echo "$k stored original seeds used: ${STORED[$k]}" || echo "$k stored original seeds MISSING"
done >"$KEEP/analysis/STORED_ARMS.txt"

PHASE=packaging
write_status RUNNING - 'packaging'
{
  echo "RUNNER_RC=0"; echo "WORK_ID=G-A085"; echo "COMPLETED_AT=$(date -Is)"
  for d in "$KEEP"/evaluation/*/; do echo "SUITE_$(basename "$d")=$(find "$d/cases" -name summary.json | wc -l)"; done
  echo "DIAG_RUNS=$(find "$KEEP/diag" -name summary.json | wc -l)"
  echo "DIAG_IDENTICAL=$(cat "$KEEP"/diag/*_PLAIN_VS_DIAG.txt | grep -c ' IDENTICAL$' || true)"
  echo "EVALUATOR_SHA=$EVALUATOR_SHA"; echo "REGISTRY_SHA=$REGISTRY_SHA"
  echo "VIDEO_STATUS=NO_VIDEO_BY_DESIGN"; echo "OFFICIAL_RESULT=OFFICIAL_RESULT_UNMEASURED"
} >"$KEEP/RUNNER_STATUS.txt"
(cd "$KEEP" && find . -type f ! -name SHA256SUMS.txt -print0 | sort -z | xargs -0 sha256sum >SHA256SUMS.txt)
SUM_DIR="$WORK/summary_bundle/go2_g_a085_precision_eval_summary"
rm -rf -- "$WORK/summary_bundle"; mkdir -p "$SUM_DIR"
(cd "$KEEP" && find . \( -name summary.json -o -name identity.json -o -name STATUS.txt -o -name case_identity.sha256 \) -print0 \
   | xargs -0 -I{} cp --parents {} "$SUM_DIR/")
cp -a "$KEEP/analysis" "$KEEP/meta" "$KEEP/RUNNER_STATUS.txt" "$KEEP/SHA256SUMS.txt" "$KEEP/G_A085_OWNER.txt" "$SUM_DIR/"
cp -a "$KEEP"/diag/*_PLAIN_VS_DIAG.txt "$SUM_DIR/" 2>/dev/null || true
(cd "$KEEP" && find diag \( -name 'diag.csv.gz' -o -name 'DIAG_STATUS.txt' -o -name steps.csv \) -print0 \
   | xargs -0 -I{} cp --parents {} "$SUM_DIR/")
"${PY[@]}" "$ROOT_DIR/shared/package_go2_result.py" "$SUM_DIR" "$SUMMARY_ZIP"
sha256sum "$SUMMARY_ZIP" >"$SUMMARY_ZIP.sha256"
"${PY[@]}" "$ROOT_DIR/shared/package_go2_result.py" "$KEEP" "$RESULT_ZIP"
sha256sum "$RESULT_ZIP" >"$RESULT_ZIP.sha256"
PHASE=done
write_status DONE 0 'both archives written; commit SUMMARY (and RESULT as parts) per HANDOFF_G_A085_PC2.md'
cat "$STATUS"
echo '[DONE] GO2_G_A085_PRECISION_EVAL_READY'
